\pard\fi-450\li450\qj\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 023r-024r}}\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5209/"}{\fldrslt \plain \f0\fs24\chcbpat17 Nikolaus von Amsdorff: Brief an Georg R\u246 \'f6rer. Amsdorf tr\u246 \'f6stet R\u246 \'f6rer, der sich wegen der ausgelassenen Abs\u228 \'e4tze im 2. deutschen Band der Wittenberger Lutherausgabe unn\u246 \'f6tige Vorw\u252 \'fcrfe macht, wenn er nichts mit dem ver\u228 \'e4nderten Luthertext zu tun hat. Er dr\u228 \'e4ngt ihn, den Hergang \u246 \'f6ffentlich zu schildern, um so sein Herz zu erleichtern.}}\plain \f0\fs24  [Eisenach,] {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1555.12.13}}\plain \f0\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/"}{\fldrslt \plain \f0\fs24\chcbpat17 L. M. G. Ich hore vngerne, das ir euch so bek\u252 \'fcmert \u8230 \'85 \endash }}\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ... vnd thuts nimer, so ists alles dahin. Datum in eil am tag Luciae 1555.}}\plain \f0\fs26  
