\pard\fi-450\li450\qj\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 029v-030r}}\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5209/"}{\fldrslt \plain \f0\fs24\chcbpat17 Johann Friedrich II., der Mittlere, Johann Wilhelm und Johann Friedrich III., der J\u252 \'fcngere, Herz\u246 \'f6ge zu Sachsen: Brief an Georg R\u246 \'f6rer. Mathias Ratzeberger wird nach Jena geschickt, um den Druck der Werke Luthers zu \u252 \'fcberwachen (vgl. Ms.Bos.q.24r, Bl. 161r): >C<}}\plain \f0\fs24  [Weimar,] {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1554.06.21}}\plain \f0\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/"}{\fldrslt \plain \f0\fs24\chcbpat17 Dem wirdigen, vnsern lieben Andechtigen vnd getrewen, Magister Georgen R\u246 \'f6rer, vnd andern, so zu dem Buchdrucker handel geh\u246 \'f6ren. Von gotts gnaden Johans Friedrich der mitler, Johans Wilhelm, vnd Johans Friedrich der J\u252 \'fcngere, gebr\u252 \'fcdere, Herzogen zu Sachssen etc. Wirdiger lieben, Andechtiger, vnd getrewen. Wir haben gegenwertigen, den hochgelarten vnsern lieben getrewen, Matthesen Ratzenberger \u8230 \'85 \endash }}\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ... vnd was er mit euch schaffen wirdet euch desselben, vnd nicht anders halten, Daran thut Ir vnsere meinung. Datum Weimar Dornstags nach Viti Anno Liiii.}}\plain \f0\fs26  }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Garamond;}{\f1\fnil\fcharset0 Garamond;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red224\green224\blue224;}

