\pard\fi-450\li450\qj\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 034r-v}}\plain \f2\fs24  {\field{\*\fldinst HYPERLINK "hida://5209/"}{\fldrslt \plain \f2\fs24\chcbpat17 Nikolaus von Amsdorff: Brief an Georg R\u246 \'f6rer \u252 \'fcber seine Sammlung, die nach Spalatins Auskunft St\u252 \'fccke enth\u228 \'e4lt, die er f\u252 \'fcr seine Arbeit gebrauchen kann: >2<}}\plain \f2\fs24  Magdeburg, {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1537.04.15}}\plain \f2\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/"}{\fldrslt \plain \f2\fs24\chcbpat17 Vero theologo atque erudito, Magistro Georgio ... \endash }}\plain \f2\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ... id idem Mgr. Benedictus eum suo collega faciet. Vale et deum pro nobis ora. Magdeburge dominica miseriocordia domini 1537.}}}

