\pard\fi-450\li450\qj\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 034v}}\plain \f2\fs24  {\field{\*\fldinst HYPERLINK "hida://5209/"}{\fldrslt \plain \f2\fs24\chcbpat17 Nikolaus von Amsdorff: Brief an Johann Stoltz in Weimar \u252 \'fcber R\u246 \'f6rer, der sich ungerecht behandelt f\u252 \'fchlt wegen der Vorw\u252 \'fcrfe, die Amsdorf 1549 gegen ihn wegen des 2. deutschen Bandes der Wittenberger Lutherausgabe erhoben hatte: >4<}}\plain \f2\fs24  Eisenach, {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1553.11.14}}\plain \f2\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/"}{\fldrslt \plain \f2\fs24\chcbpat17 M. Rorarius potimus vir agnoscit culpam, vbi nulla est ... \endash }}\plain \f2\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ... ago certe nemini vtilis esse possum. Eisenach Dinstag nach Martini 1553. N. Amsdorfius. Amantissimo suo in dominum frater, Johann Stoltzio doctiss. et pio Christi ministro, Vimariae in aula.}}}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Garamond;}{\f2\fnil\fcharset1 Garamond;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red224\green224\blue224;}

