\pard\fi-450\li450\qj\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 036r-v}}\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5209/"}{\fldrslt \plain \f0\fs24\chcbpat17 Johann Friedrich II., der Mittlere, Johann Wilhelm und Johann Friedrich III., der J\u252 \'fcngere, Herz\u246 \'f6ge zu Sachsen: Brief an Georg R\u246 \'f6rer. Die Herz\u246 \'f6ge stellen R\u246 \'f6rer Johann Aurifaber beim Druck der Lutherausgabe zur Seite, da der Druck bisher noch nicht begonnen hat: >F<}}\plain \f0\fs24  [Weimar,] {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1554.07.24}}\plain \f0\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/"}{\fldrslt \plain \f0\fs24\chcbpat17 Dem Ehrwirdigen vnserm lieben andechtigen Ern Magister Georgen R\u246 \'f6rer zu Jhene. Von Gotts gnaden Johans Fridrich der Mittler, Johans Wilhelm, vnd Johans Fridrich der J\u252 \'fcnger, Gebr\u252 \'fcdere, Hertzogen zu Sachsen. Wirdiger lieber Andechtiger. Wir werden berichtet, das vber allen vnsern angewandten gnedigen vleis mit dem druck zu Jhena noch nicht angefangen ist worden \u8230 \'85 \endash }}\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ... an ewrem getrewen vleis nichts lassen erwinden, wie wir vns zu euch gnediglich verstehen, Vnd geschicht daran vnser gefellige meinunge. Datum Dienstags nach Marie Magdalenae Anno 53.}}\plain \f0\fs26  }

