\pard\fi-450\li450\qj\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 037r-v}}\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5209/"}{\fldrslt \plain \f0\fs24\chcbpat17 Johann Friedrich II., der Mittlere, Johann Wilhelm und Johann Friedrich III., der J\u252 \'fcngere, Herz\u246 \'f6ge zu Sachsen: Brief an Georg R\u246 \'f6rer und Johann Aurifaber (?). Die Herz\u246 \'f6ge fordern beide Korrektoren auf zusammen zu arbeiten, da sie \u252 \'fcber die jeweilige Arbeit des anderen Bescheid wissen m\u252 \'fcssen: >H<}}\plain \f0\fs24  Weimar, {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1555.04.02}}\plain \f0\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/"}{\fldrslt \plain \f0\fs24\chcbpat17 Von Gotts gnaden Johans Fridrich der Mitler, Johans Wilhelm, vnd Johans Fridrich der J\u252 \'fcnger, Gebr\u252 \'fcdere, Hertzogen zu Sachssen etc. Ehrwirdiger lieber andechtiger, vnd getrewer. Nach dem ir wisset, das wir verordnunge vnd verschaffunge gethan \u8230 \'85 \endash }}\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ... vnd solcher Correctur halben im Fall der not rechenschafft vnd antwort geben k\u246 \'f6nne. Daran thut ir vnsere gefellige meinunge, vnd wir sind euch mit gnaden geneigt. Datum Weymar Dienstags nach Judica Anno 1555.}}\plain \f0\fs26  }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Garamond;}{\f2\fnil\fcharset1 Garamond;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red224\green224\blue224;}

