\pard\fi-450\li450\qj\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 037v-038v}}\plain \f2\fs24  {\field{\*\fldinst HYPERLINK "hida://5209/"}{\fldrslt \plain \f2\fs24\chcbpat17 Johann Friedrich II., der Mittlere, Johann Wilhelm und Johann Friedrich III., der J\u252 \'fcngere, Herz\u246 \'f6ge zu Sachsen: Brief an Georg R\u246 \'f6rer. Die Herz\u246 \'f6ge r\u252 \'fcgen R\u246 \'f6rer f\u252 \'fcr seine selbst\u228 \'e4ndigen \u196 \'c4nderungen in einigen Texten Luthers in der Jenaer Ausgabe. Die fordern von ihm, dies zu unterlassen und sich an die Vorgaben zu halten. Schlie\u223 \'dflich bitten sie ihn um einen Katalog seiner Handschriften. Er soll seine Handschriften nicht in Wittenberg oder bei fremden Buchdruckern ver\u246 \'f6ffentlichen: >I<}}\plain \f2\fs24  Weimar, {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1555.04.17}}\plain \f2\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/"}{\fldrslt \plain \f2\fs24\chcbpat17 Wirdiger lieber andechtiger. Wir wissen euch nicht zu bergen, das vns gleublichen anlangt, als ob solle durch euch in den ersten ausgegangenen, vnd zu Jhene gedruckten Tomo etliche worter in Doctor Martini Luthers gottseligen Vorrede vber den ersten deudschen Tomum vor zwelf [dar\u252 \'fcber: XVI] iaren ausgangen, verendert worden sein \u8230 \'85 \endash }}\plain \f2\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ... wie wir vns zu euch gentzlich vnd gnediglich versehen, daran geschicht vnser gefellige meinung vnd seind euch mit gnaden geneigt. Datum Weymar mitwoch nach dem heiligen Ostertag Anno Domini MDLV.}}\plain \f2\fs26  
\par \pard\fi-450\li450\qj\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/"}{\fldrslt \plain \f2\fs20\chcbpat17 Unschuldige Nachrichten}}\plain \f2\fs20  {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8334/"}{\fldrslt \plain \f2\fs20\chcbpat17 1726, S. 754-756}}\plain \f2\fs20 .}

