\pard\fi-450\li450\qj\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 039r}}\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5209/"}{\fldrslt \plain \f0\fs24\chcbpat17 Johann Friedrich II., der Mittlere, Johann Wilhelm und Johann Friedrich III., der J\u252 \'fcngere, Herz\u246 \'f6ge zu Sachsen: Brief an Georg R\u246 \'f6rer. Die Herz\u246 \'f6ge bitten R\u246 \'f6rer um Unterst\u252 \'fctzung f\u252 \'fcr Johann Aurifaber, der weitere Korrekturen f\u252 \'fcr den dritten Band der Jenaer Lutherwerke machen soll.}}\plain \f0\fs24  Saalfeld, {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1555.07.06}}\plain \f0\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/"}{\fldrslt \plain \f0\fs24\chcbpat17 Von Gottes gnaden Johans Fridrich der Mitler, vnd Johans Fridrich der J\u252 \'fcnger, Gebr\u252 \'fcdere Hertzogen zu Sachsen etc. Ehrwirdiger lieber andechtiger. Wir haben dem wirdigen, vnserm hoffprediger vnd auch lieben andechtien Magister Johan Goldschmiden \u8230 \'85 \endash }}\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ... Daran thut ir vnser gefellige meinunge vnd wir wollens euch, deme wir mit gnaden geneigt sind, nicht verhalten. Datum Salfeld Dornstag nach Visitationis Marie Anno Domini 1555.}}\plain \f0\fs26  }

