\pard\fi-450\li450\qj\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/"}{\fldrslt \plain \f2\fs24\chcbpat17 045r-046r}}\plain \f2\fs24  {\field{\*\fldinst HYPERLINK "hida://5209/"}{\fldrslt \plain \f2\fs24\chcbpat17 Matth\u228 \'e4us Ratzeberger. Brief an Basilius Monner in Jena. Ratzeberger erinnert an die in Weimar getroffene Verabredung, dass die Theologen einen Katalog f\u252 \'fcr den Druck anfertigen und er das n\u246 \'f6tige Geld zu besorgen habe. Dies ist so nicht geschehen, vielmehr werde in Jena der Druck der Werke Luthers verz\u246 \'f6gert. Die Schuld trifft besonders Georg R\u246 \'f6rer, der mit Arbeit \u252 \'fcberlastet ist. Er soll entlastet werden, weil Ratzeberger sich sonst gen\u246 \'f6tigt sieht, die Verz\u246 \'f6gerungen \u246 \'f6ffentlich zu machen: >B<}}\plain \f2\fs24  [Erfurt, 1. H\u228 \'e4lfte Februar {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/"}{\fldrslt \plain \f2\fs24\chcbpat17 1555}}\plain \f2\fs24 ]: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/"}{\fldrslt \plain \f2\fs24\chcbpat17 Magnifico et exellentissimo Viro, Domino Basilio Monnero J.J. Doctri ac Rectori Academiae Jhenensis, Domino et compatri suo, carissimo, et plurimum obseruando. ... \endash }}\plain \f2\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/"}{\fldrslt \plain \f2\fs24\chcbpat17 ... gelt so auffzubringen, hat es gar kein mangel.}}}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Garamond;}{\f2\fnil\fcharset1 Garamond;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red224\green224\blue224;\red204\green238\blue221;\red255\green204\blue153;}

