\pard\fi-450\li450\qj\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 046r-048v}}\plain \f2\fs24  {\field{\*\fldinst HYPERLINK "hida://5209/"}{\fldrslt \plain \f2\fs24\chcbpat17 Matth\u228 \'e4us Ratzeberger: Brief an Georg R\u246 \'f6rer mit Antwort auf einen Brief R\u246 \'f6rers, in dem er verschiedene Beschwerden vorgebracht hatte. Ratzeberger ermahnt ihn freundschaftlich, bei den einmal getroffenen Absprachen zu bleiben. Er kritisiert die Einteilung des ersten Bandes der Jenaer Lutherausgabe. Ferner fordert er R\u246 \'f6rer auf, geduldig auf die Bezahlung zu warten. Noch ist es nicht m\u246 \'f6glich, ihm einen Gehilfen an die Seite zu stellen: >C<}}\plain \f2\fs24  [Erfurt, Fr\u252 \'fchjahr {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1555}}\plain \f2\fs24 ]: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/"}{\fldrslt \plain \f2\fs24\chcbpat17 Dem wirdigen vnd wolgelarten Herrn M. Georgio Rorer Meinem gunstigen Herrn vnd guttem freunde zu handen. Gand vnd fried von Gott, dem Vater durch Jhesum Christum, vnsern Herrn. Amen Wirdiger vnd wolgelarter Herr. Ich kann euch auff ewer schreiben zur Antwort nicht verhalten ... \endash }}\plain \f2\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ... Letzlich achtet M. Andreas fur gut das man aus den ersten Commentariis ad Galatas das beste hette ausgelesen vnd hinden an gedruck in primum Tomum Latinum.}}}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Garamond;}{\f2\fnil\fcharset1 Garamond;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red224\green224\blue224;\red204\green238\blue221;\red255\green204\blue153;}

