\pard\fi-450\li450\qj\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 048v-050r}}\plain \f2\fs24  {\field{\*\fldinst HYPERLINK "hida://5209/"}{\fldrslt \plain \f2\fs24\chcbpat17 Matth\u228 \'e4us Ratzeberger: Brief an Georg R\u246 \'f6rer \u252 \'fcber seine Missbilling der Zus\u228 \'e4tze R\u246 \'f6rers in der Jenaer Lutherausgabe, da keiner das Recht hat die Texte Luthers zu ver\u228 \'e4ndern als der Autor allein. Auch Dinge, die R\u246 \'f6rer vom H\u246 \'f6ren wei\u223 \'df, geh\u246 \'f6ren nicht in die Textausgabe. Zumal das Privileg der Herz\u246 \'f6ge und die Vorrede Amsdorffs beteuern, dass es sich um unver\u228 \'e4nderte Texte handele. Ratzeberger will sich daf\u252 \'fcr einsetzen, dass R\u246 \'f6rer Gehilfen bekommt, die ihm die Arbeit erleichtern. Die Frage wegen der Pillen konnte er nicht lesen und bittet R\u246 \'f6rer, ihm erneut zu schreiben: >D<}}\plain \f2\fs24  [Erfurt, Fr\u252 \'fchjahr {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1555}}\plain \f2\fs24 ]: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/"}{\fldrslt \plain \f2\fs24\chcbpat17 S. per christum wirdiger vnd wolgelarter herr Magister, das ich euch auff ewer vielfeltiges schreiben bis daher nicht geantwortet habe ... \endash }}\plain \f2\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ... so kann ich das erste wort nicht lesen, derhalben m\u252 \'fcget ir mirs bass geschrieben zuschicken.}}}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Garamond;}{\f2\fnil\fcharset1 Garamond;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red224\green224\blue224;\red204\green238\blue221;\red255\green204\blue153;}

