\pard\fi-450\li450\qj\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 161v-162r}}\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5209/"}{\fldrslt \plain \f0\fs24\chcbpat17 Johann Friedrich II., der Mittlere, Herzog von Sachsen: Brief an Georg R\u246 \'f6rer und seine Gehilfen in Jena. Die Herz\u246 \'f6ge ordnen an, dass der Druck der Werke Luthers genau nach ihren Vorgaben zu erfolgen habe. Amsdorff und Stoltz sollen eine Vorrede schreiben. Das Privileg wird erst nach genauer Pr\u252 \'fcfung vergeben (vgl. Ms.Bos.q.24t, 030r-031r)}}\plain \f0\fs24 .[Weimar,] {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1554.06.25}}\plain \f0\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/"}{\fldrslt \plain \f0\fs24\chcbpat17 Dem Ehrwirdigen, vnserm lieben Andechtigen vnd getrewen Magister Georgen R\u246 \'f6rer, vnd andern so zum Buchhandel geh\u246 \'f6ren. Von Gotts gnaden, Johans Friedrich der Mittler, Johans Wilhelm, vnd Johans Friedrich der J\u252 \'fcnger, gebr\u252 \'fcder, Hertzogen zu Sachssen etc. Ehrwirdiger, lieben andechtiger vnd getreuer, Nach dem wir Euch durch hochgelarten vnsern auch lieben getreuen Doctor Matthesen Ratzeberger, etzliche Artickel f\u252 \'fcrhalten lassen \u8230 \'85 \endash }}\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ... Wollen wir ein Neues darnach verfertigen lassen. Daran geschicht vnsere meinunge. Datum Weymar Montags nach Johannis Baptiste 1554.}}\plain \f0\fs26  
\par \pard\fi-450\li450\qj\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/"}{\fldrslt \plain \f0\fs20\chcbpat17 Wolgast, Der Streit, 1968}}\plain \f0\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8334/"}{\fldrslt \plain \f0\fs20\chcbpat17 S. 180, Anm. 11}}\plain \f0\fs20 .}

